impl DefaultMetadataService {
    /// Execute `sql` and collect all rows from the `QueryEvent` stream into a
    /// flat `Vec<Vec<CellValue>>`. Uses a generous row buffer (1000) since
    /// metadata queries are small result sets.
    async fn collect_rows(
        &self,
        profile: ConnectionProfile,
        sql: &str,
    ) -> StudioResult<Vec<Vec<CellValue>>> {
        // Full values: metadata rows carry object definitions (view, trigger,
        // and routine source) that must not be cut to the grid's 8 KiB preview.
        let handle = self
            .queries
            .execute_full_values(&profile, None, sql, 1000)
            .await?;
        let mut events = handle.events;
        // Rows keyed by result set index; a spill manifest's COMPLETE on-disk
        // set supersedes the forwarded prefix for its index — the executor
        // withholds payloads past its row threshold or byte budget.
        let mut by_index: std::collections::BTreeMap<usize, Vec<Vec<CellValue>>> =
            std::collections::BTreeMap::new();
        while let Some(event) = events.recv().await {
            match event {
                QueryEvent::Rows { index, rows } => by_index.entry(index).or_default().extend(rows),
                QueryEvent::SpillManifest { manifest } => {
                    for set in &manifest.result_sets {
                        if let Some(rows) = take_spilled_rows(set) {
                            by_index.insert(set.result_set_index, rows);
                        }
                    }
                }
                QueryEvent::Error { message } => {
                    return Err(StudioError::Connection(message));
                }
                QueryEvent::Completed { .. } | QueryEvent::Cancelled => break,
                _ => {}
            }
        }
        Ok(by_index.into_values().flatten().collect())
    }
}

/// Clone the profile with the database overridden for metadata queries.
pub(crate) fn profile_with_db(profile: &ConnectionProfile, database: &str) -> ConnectionProfile {
    let mut p = profile.clone();
    // An empty name means "wherever the profile already points": server-scope
    // queries have no database of their own, and blanking the profile's would
    // connect to nothing.
    if !database.is_empty() {
        p.database = Some(database.to_string());
    }
    p
}

pub(crate) fn cell_to_string(cell: Option<CellValue>) -> Option<String> {
    match cell? {
        CellValue::Null => None,
        CellValue::Bool(b) => Some(b.to_string()),
        CellValue::I64(n) => Some(n.to_string()),
        CellValue::F64(n) => Some(n.to_string()),
        CellValue::String(s) => Some(s),
        CellValue::Bytes(_) => None,
    }
}

pub(crate) fn cell_to_i64(cell: Option<CellValue>) -> Option<i64> {
    match cell? {
        CellValue::Null => None,
        CellValue::I64(n) => Some(n),
        CellValue::F64(n) => Some(n as i64),
        CellValue::Bool(b) => Some(b as i64),
        CellValue::String(s) => s.parse().ok(),
        CellValue::Bytes(_) => None,
    }
}

/// Format a procedure parameter's SQL type the same way as column types.
fn parameter_type_detail(
    type_name: &str,
    max_length: Option<i64>,
    precision: Option<i64>,
    scale: Option<i64>,
) -> String {
    render_sql_type(type_name, max_length, precision, scale)
}

pub(crate) fn cell_to_bool(cell: Option<CellValue>) -> Option<bool> {
    match cell? {
        CellValue::Null => None,
        CellValue::Bool(b) => Some(b),
        CellValue::I64(n) => Some(n != 0),
        CellValue::F64(n) => Some(n != 0.0),
        CellValue::String(s) => Some(s.eq_ignore_ascii_case("true") || s == "1"),
        CellValue::Bytes(_) => None,
    }
}

fn trigger_detail(is_disabled: bool) -> Option<String> {
    if is_disabled {
        Some("disabled".into())
    } else {
        None
    }
}

fn database_trigger_row_to_node(row: Vec<CellValue>) -> Option<MetadataNode> {
    let mut cells = row.into_iter();
    let schema = cell_to_string(cells.next());
    let name = cell_to_string(cells.next())?;
    let _parent = cells.next();
    let is_disabled = cell_to_bool(cells.next()).unwrap_or(false);
    let mut node = MetadataNode::new(name, ObjectKind::Trigger);
    if let Some(schema) = schema.filter(|s| !s.is_empty()) {
        node = node.with_schema(schema);
    }
    if let Some(detail) = trigger_detail(is_disabled) {
        node = node.with_detail(detail);
    }
    Some(node)
}

fn sequence_row_to_node(row: Vec<CellValue>) -> Option<MetadataNode> {
    let mut cells = row.into_iter();
    let schema = cell_to_string(cells.next())?;
    let name = cell_to_string(cells.next())?;
    let data_type = cell_to_string(cells.next()).unwrap_or_default();
    let start = cell_to_string(cells.next()).unwrap_or_else(|| "?".into());
    let increment = cell_to_string(cells.next()).unwrap_or_else(|| "?".into());
    let _current = cells.next();
    let detail = format!("{data_type} · start {start} · step {increment}");
    Some(
        MetadataNode::new(name, ObjectKind::Sequence)
            .with_schema(schema)
            .with_detail(detail),
    )
}

fn available_extension_row_to_node(row: Vec<CellValue>) -> Option<MetadataNode> {
    let mut cells = row.into_iter();
    let name = cell_to_string(cells.next())?;
    let version = cell_to_string(cells.next()).unwrap_or_default();
    let _description = cells.next();
    let installed = cell_to_bool(cells.next()).unwrap_or(false);
    let installed_label = if installed {
        "installed"
    } else {
        "not installed"
    };
    let detail = format!("{version} · {installed_label}");
    Some(MetadataNode::new(name, ObjectKind::Extension).with_detail(detail))
}

fn materialized_view_row_to_node(row: Vec<CellValue>) -> Option<MetadataNode> {
    let mut cells = row.into_iter();
    let schema = cell_to_string(cells.next())?;
    let name = cell_to_string(cells.next())?;
    let is_populated = cell_to_bool(cells.next()).unwrap_or(false);
    let detail = if is_populated {
        "populated"
    } else {
        "not populated"
    };
    Some(
        MetadataNode::new(name, ObjectKind::MaterializedView)
            .with_schema(schema)
            .with_detail(detail),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn metadata_node_qualified_name() {
        let n = MetadataNode::new("Orders", ObjectKind::Table).with_schema("dbo");
        assert_eq!(n.qualified_name(), "dbo.Orders");
        let n2 = MetadataNode::new("sp_exec", ObjectKind::StoredProcedure);
        assert_eq!(n2.qualified_name(), "sp_exec");
    }

    #[test]
    fn column_detail_uses_canonical_type_rendering() {
        use sqlly_intel::metadata::ddl::render_sql_type;
        assert_eq!(render_sql_type("int", Some(4), Some(10), Some(0)), "int");
        assert_eq!(
            render_sql_type("nvarchar", Some(200), Some(0), Some(0)),
            "nvarchar(100)"
        );
        assert_eq!(
            render_sql_type("nvarchar", Some(-1), Some(0), Some(0)),
            "nvarchar(max)"
        );
        assert_eq!(
            render_sql_type("decimal", Some(9), Some(18), Some(2)),
            "decimal(18,2)"
        );
        assert_eq!(
            render_sql_type("datetime", Some(8), Some(23), Some(3)),
            "datetime"
        );
    }

    #[test]
    fn procedure_parameter_type_uses_canonical_type_rendering() {
        assert_eq!(
            parameter_type_detail("nvarchar", Some(200), Some(0), Some(0)),
            "nvarchar(100)"
        );
        assert_eq!(
            parameter_type_detail("nvarchar", Some(-1), Some(0), Some(0)),
            "nvarchar(max)"
        );
        assert_eq!(
            parameter_type_detail("decimal", Some(9), Some(18), Some(2)),
            "decimal(18,2)"
        );
        assert_eq!(
            parameter_type_detail("int", Some(4), Some(10), Some(0)),
            "int"
        );
    }

    #[test]
    fn cell_to_string_conversions() {
        assert_eq!(
            cell_to_string(Some(CellValue::String("hello".into()))),
            Some("hello".into())
        );
        assert_eq!(cell_to_string(Some(CellValue::I64(42))), Some("42".into()));
        assert_eq!(cell_to_string(Some(CellValue::Null)), None);
    }

    #[test]
    fn cell_to_bool_conversions() {
        assert_eq!(cell_to_bool(Some(CellValue::Bool(true))), Some(true));
        assert_eq!(cell_to_bool(Some(CellValue::I64(1))), Some(true));
        assert_eq!(cell_to_bool(Some(CellValue::I64(0))), Some(false));
        assert_eq!(
            cell_to_bool(Some(CellValue::String("true".into()))),
            Some(true)
        );
        assert_eq!(cell_to_bool(Some(CellValue::Null)), None);
    }

    #[test]
    fn profile_with_db_overrides_database() {
        let profile = ConnectionProfile::sql_login(
            "test",
            "server",
            "sa",
            sqlly_core::SecretRef {
                provider: sqlly_core::SecretProvider::InMemory,
                key: "pw".into(),
            },
        );
        let p = profile_with_db(&profile, "master");
        assert_eq!(p.database.as_deref(), Some("master"));
        assert_eq!(p.server, "server");
    }

    #[test]
    fn sequences_rows_map_to_nodes_with_detail() {
        let node = sequence_row_to_node(vec![
            CellValue::String("public".into()),
            CellValue::String("users_id_seq".into()),
            CellValue::String("bigint".into()),
            CellValue::I64(1),
            CellValue::I64(1),
            CellValue::Null,
        ])
        .unwrap();
        assert_eq!(node.name, "users_id_seq");
        assert_eq!(node.schema.as_deref(), Some("public"));
        assert_eq!(node.kind, ObjectKind::Sequence);
        assert_eq!(node.detail.as_deref(), Some("bigint · start 1 · step 1"));
    }

    #[test]
    fn available_extensions_flag_installed() {
        let installed = available_extension_row_to_node(vec![
            CellValue::String("pgcrypto".into()),
            CellValue::String("1.3".into()),
            CellValue::String("cryptographic functions".into()),
            CellValue::I64(1),
        ])
        .unwrap();
        assert_eq!(installed.name, "pgcrypto");
        assert_eq!(installed.detail.as_deref(), Some("1.3 · installed"));

        let available = available_extension_row_to_node(vec![
            CellValue::String("postgis".into()),
            CellValue::String("3.4".into()),
            CellValue::String("PostGIS geometry".into()),
            CellValue::I64(0),
        ])
        .unwrap();
        assert_eq!(available.detail.as_deref(), Some("3.4 · not installed"));
    }

    #[test]
    fn trigger_detail_omits_active_label() {
        assert_eq!(trigger_detail(false), None);
        assert_eq!(trigger_detail(true).as_deref(), Some("disabled"));
    }
}
